import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·20","description":"易小帖 - 卷四·20","frontmatter":{"title":"卷四·20","description":"易小帖 - 卷四·20"},"headers":[],"relativePath":"classics/yixiaotie/114.md","filePath":"classics/yixiaotie/114.md"}'),o={name:"classics/yixiaotie/114.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·20",tabindex:"-1"},[r("卷四·20 "),e("a",{class:"header-anchor",href:"#卷四·20","aria-label":"Permalink to “卷四·20”"},"​")],-1),e("p",null,"陰陽有九六又有七八，舊亦未解。《春秋》穆薑將往東宮，筮之，得艮之八，史曰「是謂艮之隨」，杜預謂：艮者艮下艮上之卦也，《周禮》太卜掌三易，雜用連山、歸藏，周易，謂之三易。連山、歸藏皆以七八為佔。而其說未解。如曰七八即九六，夏商以陽陰為七八，猶周以陽陰為九六，則其曰艮之陰不可解，豈艮四陰爻皆佔耶。如曰：除本卦六爻外以之卦之初爻為七，之卦之二爻為八，則何以無九、十十一、十二，豈之卦必限於初與二耶。如曰老陽為九，老陰為六，少陽為七，少陰為八，老變而少不變，夏商佔易皆以不變者為佔，故佔七八，則此遇艮之八即遇艮之隨，隨止第二爻不變，若《國語》遇泰之八，即遇泰之豫，豫則上與五皆不變矣。不止一八矣。然亦曰，之八將之上之八耶？之五之八耶？且有遇貞屯悔豫皆八者，不知遇卦之卦何謂皆八？何謂皆不變？吾不解也。若此者闕之可也。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
